mapper.insert:
insert into post_view (post_id, ip_hash)
select #{postId}, #{ipHash}
from dual
where not exists (
    select 1 from post_view v
    where v.post_id = #{postId} and v.ip_hash = #{ipHash}
)

mapper.select:
select from post p join app_user u on u.id = p.author_id join post_like l on l.post_id = p.id where l.user_id = #{userId}
and p.visibility = 'PUBLIC' and p.status = 'PUBLISHED'
order by l.created_at desc, l.id desc limit #{limit} offset #{offset}
